/** A pixel's colour key; '.' is transparent. */
export type Key = '.' | 'W' | 'T' | 'S' | 'D' | 'G' | 'O' | 'R' | 'Y' | 'B' | 'E' | 'H' | 'K' | 'X'
export type Ink = Exclude<Key, '.'>
export type Palette = Record<Ink, string>

export const BRAND = { red: '#E5483B', blue: '#1E90F0', yellow: '#F7D23A', white: '#FFFFFF' } as const

// W front, T lid, S side, D crease, G speckle, R/Y/B badge and dust, E eyes and mouth, H eye glint, K cheeks.
const BASE = {
  W: '#F4F6F9',
  T: BRAND.white,
  S: '#D5DAE2',
  D: '#C3C9D3',
  G: '#E3E7ED',
  R: BRAND.red,
  Y: BRAND.yellow,
  B: BRAND.blue,
  E: '#1E2230',
  H: BRAND.white,
  K: '#F6A39B',
} as const

/** For white and light pages: a dark outline (O) and a soft grey shadow (X). */
export const LIGHT: Palette = { ...BASE, O: '#2B3040', X: '#D3D7DE' }
/** For dark terminals: a lighter rim so the silhouette holds, and a near-black shadow. */
export const DARK: Palette = { ...BASE, O: '#6B7488', X: '#0E1016' }

export type Mood = 'idle' | 'working' | 'waiting' | 'error' | 'done' | 'sleep'
export const MOODS: readonly Mood[] = ['idle', 'working', 'waiting', 'error', 'done', 'sleep']
export type Grid = Key[][]
export type Frame = { grid: Grid; ms: number }

export const MIN_SIZE = 16
export const TERMINAL_SIZE = 18
export const WEB_SIZE = 26

type Eyes = 'open' | 'closed' | 'happy' | 'shocked'
type Mouth = 'smile' | 'open' | 'oh' | 'flat'
type Shape = 'n' | 'squash' | 'stretch'
/** One frame's pose: lift is a share (0-1) of the room above the cube; look shifts the eyes; dx shakes the body. */
type Pose = {
  shape: Shape
  lift: number
  eyes: Eyes
  mouth: Mouth
  look: number
  up: boolean
  dx: number
  flash: boolean
  dust?: number
  ask: boolean
  z?: number
  ms: number
}

const pose = (ms: number, o: Partial<Pose> = {}): Pose => ({
  shape: 'n',
  lift: 0,
  eyes: 'open',
  mouth: 'smile',
  look: 0,
  up: false,
  dx: 0,
  flash: false,
  ask: false,
  ms,
  ...o,
})

